16686:## Knowledge base: Valheim
import { db } from "./db";
import type { Prisma } from "@prisma/client";

/**
 * IPAM — private-IP and SSH-forward-port allocation.
 *
 * Node-aware: when a `nodeId` is supplied the pool is taken from that Node's
 * configured range (`subnetPrefix` / `ipStart` / `ipEnd` / `sshPortStart` /
 * `sshPortEnd`). Without a nodeId we fall back to the global env range, which is
 * the single-node behaviour this module has always had.
 *
 * Race safety: `Server.ipAddress` and `Server.sshPort` are UNIQUE columns, so a
 * concurrent double-provision must not hand out the same value twice. When the
 * caller passes the server it is allocating for, the "find free + claim" pair
 * runs inside a single transaction guarded by a Postgres advisory lock, with a
 * retry loop on unique-constraint conflicts. Callers that do not pass a server
 * id get a best-effort pick plus a short-lived in-process reservation (which
 * covers concurrent jobs inside one worker process, the common case).
 *
 * `allocateSandboxVmid` below shares this same lock + retry machinery for a
 * third UNIQUE column, `Server.vmid`, in NXEON_SANDBOX mode (see its own doc
 * comment for the incident that made that necessary).
 */

const ENV_SUBNET_PREFIX = process.env.NXEON_SUBNET_PREFIX ?? "10.20.0.";
const IP_START = Number(process.env.NXEON_IP_START ?? 100);
const IP_END = Number(process.env.NXEON_IP_END ?? 250);
export const SSH_PORT_START = Number(process.env.NXEON_SSH_PORT_START ?? 20000);
export const SSH_PORT_END = Number(process.env.NXEON_SSH_PORT_END ?? 29999);

/** Advisory-lock key that serialises IPAM allocation across processes. */
const IPAM_LOCK_KEY = 728_144_301;
/** How many times we re-pick after losing a unique-constraint race. */
const CLAIM_ATTEMPTS = 8;
/** How long an unclaimed hand-out is remembered in this process. */
const RESERVATION_TTL_MS = 10 * 60_000;
/**
 * Sandbox-only vmids live at 990001+ — comfortably clear of any real Proxmox
 * id (those start at 100) so a sandbox value can never collide with one if a
 * tree is ever pointed at a real cluster by mistake. See `allocateSandboxVmid`.
 */
const SANDBOX_VMID_BASE = 990_000;

export type IpamRange = {
  nodeId: string | null;
  subnetPrefix: string;
  ipStart: number;
  ipEnd: number;
  sshPortStart: number;
  sshPortEnd: number;
  bridge: string | null;
  natChain: string | null;
};

const GLOBAL_RANGE: IpamRange = {
  nodeId: null,
  subnetPrefix: ENV_SUBNET_PREFIX,
  ipStart: IP_START,
  ipEnd: IP_END,
  sshPortStart: SSH_PORT_START,
  sshPortEnd: SSH_PORT_END,
  bridge: process.env.NXEON_BRIDGE ?? null,
  natChain: process.env.NXEON_NAT_CHAIN ?? null,
};

const num = (v: unknown, fallback: number) =>
  typeof v === "number" && Number.isFinite(v) ? v : fallback;

/**
 * Resolve the pool a node allocates from. Unknown/empty node fields fall back to
 * the global env values so a half-configured Node row can never produce an
 * empty range.
 */
export async function ipamRange(nodeId?: string | null): Promise<IpamRange> {
  if (!nodeId) return { ...GLOBAL_RANGE };
  const node = await db.node.findUnique({
    where: { id: nodeId },
    select: {
      id: true,
      subnetPrefix: true,
      ipStart: true,
      ipEnd: true,
      sshPortStart: true,
      sshPortEnd: true,
      bridge: true,
      natChain: true,
    },
  });
  if (!node) return { ...GLOBAL_RANGE };
  const prefix = node.subnetPrefix?.trim() || GLOBAL_RANGE.subnetPrefix;
  return {
    nodeId: node.id,
    subnetPrefix: prefix.endsWith(".") ? prefix : `${prefix}.`,
    ipStart: num(node.ipStart, GLOBAL_RANGE.ipStart),
    ipEnd: num(node.ipEnd, GLOBAL_RANGE.ipEnd),
    sshPortStart: num(node.sshPortStart, GLOBAL_RANGE.sshPortStart),
    sshPortEnd: num(node.sshPortEnd, GLOBAL_RANGE.sshPortEnd),
    bridge: node.bridge ?? GLOBAL_RANGE.bridge,
    natChain: node.natChain ?? GLOBAL_RANGE.natChain,
  };
}

// ---------- in-process reservations ----------

const reservations = new Map<string, number>();

function isReserved(key: string): boolean {
  const until = reservations.get(key);
  if (until === undefined) return false;
  if (until <= Date.now()) {
    reservations.delete(key);
    return false;
  }
  return true;
}

function reserve(key: string): void {
  if (reservations.size > 5000) {
    const now = Date.now();
    for (const [k, until] of reservations) if (until <= now) reservations.delete(k);
  }
  reservations.set(key, Date.now() + RESERVATION_TTL_MS);
}

function isUniqueConflict(e: any): boolean {
  return e?.code === "P2002";
}

type Tx = Prisma.TransactionClient;

/**
 * Serialise allocators across processes with a transaction-scoped advisory lock
 * (auto-released on commit/rollback). Support is probed once OUTSIDE a
 * transaction — a failing statement inside an open Postgres transaction would
 * abort it, so we never speculatively try it in the hot path.
 */
let advisoryLocks: boolean | null = null;
// Two workarounds baked in:
//  - the key is a literal, not a bound parameter: a bound JS number can reach
//    Postgres as `numeric` and fail to resolve the ...(bigint) overload;
//  - pg_advisory_xact_lock() returns `void`, which Prisma's $queryRaw cannot
//    deserialize, so it is wrapped in a subselect that yields an int column.
const LOCK_SQL = `SELECT 1 AS locked FROM (SELECT pg_advisory_xact_lock(${IPAM_LOCK_KEY})) _lock`;

async function lockIpam(tx: Tx): Promise<void> {
  if (advisoryLocks === false) return;
  await tx.$queryRawUnsafe(LOCK_SQL);
}

async function probeAdvisoryLocks(): Promise<void> {
  if (advisoryLocks !== null) return;
  try {
    // Take and immediately release it (xact locks drop at commit). Done once,
    // outside the hot path, because a failing statement inside an open
    // transaction would abort that transaction.
    await db.$transaction(async (tx) => {
      await tx.$queryRawUnsafe(LOCK_SQL);
    });
    advisoryLocks = true;
  } catch {
    // Not Postgres, or the role lacks permission: the unique-conflict retry
    // loop plus in-process reservations remain as the safety net.
    advisoryLocks = false;
  }
}

// ---------- IP allocation ----------

/**
 * Candidate IPs are all `<prefix><n>`, so only servers already sitting in the
 * same subnet prefix can conflict — servers on other nodes (different prefix)
 * are naturally excluded. We still read the column globally because
 * `Server.ipAddress` is globally UNIQUE: skipping a value that another node
 * happens to hold is what keeps the insert from blowing up.
 */
async function pickFreeIp(tx: Tx, range: IpamRange): Promise<string> {
  const rows = await tx.server.findMany({
    where: { ipAddress: { startsWith: range.subnetPrefix } },
    select: { ipAddress: true },
  });
  const used = new Set(rows.map((r) => r.ipAddress!).filter(Boolean));
  for (let i = range.ipStart; i <= range.ipEnd; i++) {
    const ip = `${range.subnetPrefix}${i}`;
    if (used.has(ip)) continue;
    if (isReserved(`ip:${ip}`)) continue;
    return ip;
  }
  throw new Error(
    range.nodeId
      ? `IP pool exhausted for node ${range.nodeId} (${range.subnetPrefix}${range.ipStart}-${range.ipEnd})`
      : "IP pool exhausted"
  );
}

/**
 * Allocate a private IP.
 *
 * @param nodeId          allocate from this Node's configured subnet/range.
 * @param claimForServerId when given, the IP is written onto that Server row in
 *                         the same transaction, making the allocation atomic.
 */
export async function allocateIp(
  nodeId?: string | null,
  claimForServerId?: string | null
): Promise<string> {
  const range = await ipamRange(nodeId);
  await probeAdvisoryLocks();

  if (!claimForServerId) {
    // No row to claim against: pick + reserve in-process so concurrent jobs in
    // this worker cannot be handed the same address.
    const ip = await db.$transaction(async (tx) => {
      await lockIpam(tx);
      return pickFreeIp(tx, range);
    });
    reserve(`ip:${ip}`);
    return ip;
  }

  let lastErr: unknown;
  for (let attempt = 0; attempt < CLAIM_ATTEMPTS; attempt++) {
    let ip = "";
    try {
      ip = await db.$transaction(async (tx) => {
        await lockIpam(tx);
        const candidate = await pickFreeIp(tx, range);
        await tx.server.update({
          where: { id: claimForServerId },
          data: { ipAddress: candidate },
        });
        return candidate;
      });
    } catch (e) {
      lastErr = e;
      if (isUniqueConflict(e)) {
        // Someone beat us to it between pick and claim — skip it and retry.
        continue;
      }
      throw e;
    }
    reserve(`ip:${ip}`);
    return ip;
  }
  throw new Error(
    `IP allocation contended — gave up after ${CLAIM_ATTEMPTS} attempts` +
      (lastErr ? `: ${String((lastErr as any)?.message ?? lastErr).slice(0, 160)}` : "")
  );
}

// ---------- SSH forward-port allocation ----------

/**
 * `Server.sshPort` and `PortForward.publicPort` are both globally UNIQUE, so the
 * taken-set is read globally even though the *range* we scan is per-node.
 * Node-awareness therefore comes from the range: give each node a disjoint
 * sshPortStart/sshPortEnd window and two nodes can never collide.
 */
async function pickFreePort(tx: Tx, range: IpamRange): Promise<number> {
  const [servers, forwards] = await Promise.all([
    tx.server.findMany({
      where: { sshPort: { gte: range.sshPortStart, lte: range.sshPortEnd } },
      select: { sshPort: true },
    }),
    tx.portForward.findMany({
      where: { publicPort: { gte: range.sshPortStart, lte: range.sshPortEnd } },
      select: { publicPort: true },
    }),
  ]);
  const used = new Set<number>([
    ...servers.map((s) => s.sshPort!).filter((p) => p != null),
    ...forwards.map((f) => f.publicPort),
  ]);
  for (let p = range.sshPortStart; p <= range.sshPortEnd; p++) {
    if (used.has(p)) continue;
    if (isReserved(`port:${p}`)) continue;
    return p;
  }
  throw new Error(
    range.nodeId
      ? `SSH port pool exhausted for node ${range.nodeId} (${range.sshPortStart}-${range.sshPortEnd})`
      : "SSH port pool exhausted"
  );
}

/**
 * Allocate an SSH forward port.
 *
 * @param nodeId          allocate from this Node's configured port range.
 * @param claimForServerId when given, the port is written onto that Server row
 *                         in the same transaction, making it atomic.
 */
export async function allocateSshPort(
  nodeId?: string | null,
  claimForServerId?: string | null
): Promise<number> {
  const range = await ipamRange(nodeId);
  await probeAdvisoryLocks();

  if (!claimForServerId) {
    const port = await db.$transaction(async (tx) => {
      await lockIpam(tx);
      return pickFreePort(tx, range);
    });
    reserve(`port:${port}`);
    return port;
  }

  let lastErr: unknown;
  for (let attempt = 0; attempt < CLAIM_ATTEMPTS; attempt++) {
    let port = 0;
    try {
      port = await db.$transaction(async (tx) => {
        await lockIpam(tx);
        const candidate = await pickFreePort(tx, range);
        await tx.server.update({
          where: { id: claimForServerId },
          data: { sshPort: candidate },
        });
        return candidate;
      });
    } catch (e) {
      lastErr = e;
      if (isUniqueConflict(e)) continue;
      throw e;
    }
    reserve(`port:${port}`);
    return port;
  }
  throw new Error(
    `SSH port allocation contended — gave up after ${CLAIM_ATTEMPTS} attempts` +
      (lastErr ? `: ${String((lastErr as any)?.message ?? lastErr).slice(0, 160)}` : "")
  );
}

/**
 * Allocate a sandbox vmid and claim it onto `serverId` atomically.
 *
 * NXEON_SANDBOX has no real Proxmox to hand out ids, so this used to be
 * `990000 + (await db.server.count())` inline in worker/index.ts's `provision()`.
 * That is not a per-server sequence — `count()` is just the CURRENT number of
 * Server rows, and minting a vmid fills in a column on a row that already
 * exists (checkout inserts the PENDING Server row immediately; the PROVISION
 * job that assigns `vmid` runs later, often for several orders back-to-back
 * with no new Server row created in between). Two servers provisioned while
 * the total row count hasn't moved computed the exact same vmid, and the
 * second `prisma.server.update()` died on the `vmid` unique constraint —
 * "Provisioning failed" for a customer whose order was otherwise fine.
 *
 * Fixed the same way `allocateIp`/`allocateSshPort` above fix the identical
 * class of bug for `Server.ipAddress`/`Server.sshPort`: pick MAX(vmid)+1 and
 * claim it in one transaction under the shared advisory lock, so no second
 * caller can observe the same MAX before the first one's claim lands. Where
 * advisory locks aren't available (probed once, see `probeAdvisoryLocks`) the
 * unique-constraint retry loop is the fallback, same as the IP/port allocators.
 */
export async function allocateSandboxVmid(serverId: string): Promise<number> {
  await probeAdvisoryLocks();

  let lastErr: unknown;
  for (let attempt = 0; attempt < CLAIM_ATTEMPTS; attempt++) {
    try {
      return await db.$transaction(async (tx) => {
        await lockIpam(tx);
        const highest = await tx.server.aggregate({ _max: { vmid: true } });
        const candidate = Math.max(SANDBOX_VMID_BASE, highest._max.vmid ?? SANDBOX_VMID_BASE) + 1;
        await tx.server.update({ where: { id: serverId }, data: { vmid: candidate } });
        return candidate;
      });
    } catch (e) {
      lastErr = e;
      if (isUniqueConflict(e)) continue; // lost the race — re-read MAX and retry
      throw e;
    }
  }
  throw new Error(
    `Sandbox vmid allocation contended — gave up after ${CLAIM_ATTEMPTS} attempts` +
      (lastErr ? `: ${String((lastErr as any)?.message ?? lastErr).slice(0, 160)}` : "")
  );
}

/**
 * Auto-forward a game's own port at provision time, from the SAME pool and
 * under the SAME advisory lock as SSH ports (they've always shared one range
 * — see pickFreePort, which already checks both Server.sshPort AND
 * PortForward.publicPort). Without this, a NAT (non-dedicated-IP) game
 * server's game port was reachable by nobody until the customer manually
 * added a forward from the dashboard — found live via a real customer whose
 * Minecraft server had zero forwards and no dedicated IP, so its game port
 * had no path from any public IP at all. Dedicated-IP servers need no
 * forward (their guest port IS the public port) — callers should only call
 * this for the NAT case.
 */
export async function allocateGameForward(
  nodeId: string | null | undefined,
  serverId: string,
  guestPort: number,
  protocol: "tcp" | "udp" = "tcp"
): Promise<number> {
  const range = await ipamRange(nodeId);
  await probeAdvisoryLocks();

  let lastErr: unknown;
  for (let attempt = 0; attempt < CLAIM_ATTEMPTS; attempt++) {
    let port = 0;
    try {
      port = await db.$transaction(async (tx) => {
        await lockIpam(tx);
        const candidate = await pickFreePort(tx, range);
        await tx.portForward.create({
          data: { serverId, publicPort: candidate, guestPort, protocol },
        });
        return candidate;
      });
    } catch (e) {
      lastErr = e;
      if (isUniqueConflict(e)) continue;
      throw e;
    }
    reserve(`port:${port}`);
    return port;
  }
  throw new Error(
    `Game port forward allocation contended — gave up after ${CLAIM_ATTEMPTS} attempts` +
      (lastErr ? `: ${String((lastErr as any)?.message ?? lastErr).slice(0, 160)}` : "")
  );
}

// ---------- gateway ----------

/**
 * Gateway for a NAT subnet. Backwards compatible: called with no argument it
 * returns the global gateway exactly as before. Pass a Node's `subnetPrefix`
 * (or use {@link gatewayIpForNode}) for multi-node correctness.
 */
export function gatewayIp(subnetPrefix?: string | null): string {
  const prefix = subnetPrefix?.trim() || ENV_SUBNET_PREFIX;
  return `${prefix.endsWith(".") ? prefix : `${prefix}.`}1`;
}

/** Async node-aware variant of {@link gatewayIp}. */
export async function gatewayIpForNode(nodeId?: string | null): Promise<string> {
  const range = await ipamRange(nodeId);
  return gatewayIp(range.subnetPrefix);
}

### 7. Known issues and open to-dos

| Item | State |
|---|---|
| Consecutive port allocator | Public ports are allocated one by one (`allocateGameForward` in `worker/index.ts`, called per `joinPortsFor`); N, N+1, N+2 are not guaranteed, and non-consecutive blocks break joining (Jay, 2026-10-01). To do: allocate a consecutive free block of three on the node. |
| Ballooning floor | `balloonFloorMB` = 50% of plan RAM, min 1024. On 4 GB plans a busy node squeezes the guest to ~1.8 GB. To do: no balloon (or higher floor) for game plans; existing VMs need `--balloon 0` + cold reboot by hand. |
| File manager: extract archives | Merged to main (`ca30a05922`: zip/tar/7z/rar with zip-slip/symlink/bomb guards). Prod deployment state UNVERIFIED: confirm before telling customers. |
| File manager: folder upload | Merged to main (`a6201db7ed`). Prod deployment state UNVERIFIED. Until deployed, customers can only upload files (T15). |
| World backup job locations | `GAME_CONTROL.valheim.dataRoots` (`lib/game-control.ts`) lists `/root/.config/unity3d/...`, `/home/valheim/...`, `/opt/valheim/worlds_local`, not the real `/opt/valheim/config/worlds_local`. World listing and `GAME_BACKUP` for Valheim probably find nothing. Code gap, not fixed here. |
| World-switch on settings save + restore false alarm | Fixed in `8f6066be2e` on main; prod deploy UNVERIFIED. |
| No server-name field | Valheim Settings schema has no `SERVER_NAME` field (provision hardcodes `SERVER_NAME='Nxeon'`), so console players searching by name need staff help to rename. Gap, UNVERIFIED how renaming is done today. |
| Chat bot plan knowledge | `lib/kb-plans.ts` lists only the 8 GB Valheim plan; bot denied the 4 GB plan twice (LC9, LC11). Gap. |
| Checkout password field | T7 / LC7: required `SERVER_PASS` field not rendered for a Valheim order on 2026-09-16; root cause and current state UNVERIFIED here. |
| Kick/ban/players | No native RCON: no kick/ban from the panel; leave times inferred; `<id>` in the join log is a ZDOID, not a SteamID64. |
| Old-world passwords | Pre-2026-09-08 servers may still use the shared default password. UNVERIFIED count. |
| `adminlist.txt` format and live reload | Whether live edits apply without restart, and bare vs `Steam_<id>` form: UNVERIFIED (2026-09-20 notes call this unresolved). Staff always restart. |
| Image backup defaults | Schedule/retention of the image auto-backups not read from code: UNVERIFIED. |

### 8. Customer reply templates

Keep them short, no internal jargon, no provider names, no invented timings. Replace `<...>`. Drafts only: a human must approve before any ticket reply is sent.

1. **Can't connect (first reply)**
   "Thanks for flagging this. Your server is running on our side. Please join with <ip>:<port> (Join by IP) and the server password from your Settings tab, and restart your Valheim game before trying again, as that clears a cached failed connection. If it still fails, send us a screenshot of the Join box with the error, and the list of mods you have installed on your PC, and we'll dig in right away."

2. **Version mismatch / mod parity**
   "Valheim only lets players in when their mods match the server exactly. Your server runs: <mod list with versions>. Every player needs the same mods at the same versions. If you'd rather not ask everyone to install them, tell us and we'll remove the mod on the server so everyone can join again. Note that adding or removing a mod restarts the server for a minute or two."

3. **Mod disappeared after a game update**
      // the primary has NO route to a non-primary node's private subnet at
      // all, so checking `ip` directly there fails with EHOSTUNREACH 100% of
      // the time, regardless of whether the game server is healthy. Found
      // live: the very first real customer ever freshly provisioned onto
      // node-2 hit this unconditionally — SSH passed (it already correctly
      // checks the public address), the game-port check could not, ever.
      // Fix: for a NAT (non-dedicated) server on a non-primary node, forward
      // the port FIRST (reusing an existing forward on retry rather than
      // allocating a new public port every attempt) and check through it via
      // the node's own public IP — the exact same external path a real
      // customer uses, already proven to work by the SSH check just above.
      let checkHost = ip;
      let checkPort = game.port;
      if (!SANDBOX && !dedicated && !nodeRow?.isPrimary) {
        const existing = await db.portForward.findFirst({
          where: { serverId: server.id, guestPort: game.port, protocol: game.protocol },
          select: { publicPort: true },
        });
        checkPort = existing?.publicPort ?? (await allocateGameForward(server.nodeId, server.id, game.port, game.protocol));
        const natErr = await syncPortForwardsBestEffort(`provision ${server.hostname} (game port)`);
        if (natErr) {
          throw new Error(
            `could not sync the game port forward on ${nodeRow?.name ?? "the target node"} for verification: ${natErr}`
          );
        }
        checkHost = server.node?.publicIp ?? process.env.PUBLIC_IP ?? ip;
      }

      // Same connection details the SSH check above just proved work — taken
      // from this run's own variables, NOT the stale `server` row (see
      // waitOutGameInstall's own comment for why that matters).
      const probeServer = {
        id: server.id,
        rootPassword: password,
        rootPasswordEnc: null,
        sshPort: dedicated ? 22 : sshPort,
        dedicatedIp: dedicated ? { address: dedicated.address } : null,
        node: server.node,
      };
      // The external probe alone cannot pass a UDP family honestly — it reports
      // success on silence. Pair it with positive evidence from inside the guest.
      const verifyBound = () => gamePortBoundInGuest(probeServer, game.port, game.protocol);

      const gameCheck = await checkGamePortOpen(checkHost, checkPort, game.protocol, { verifyBound });
      if (!gameCheck.ok) {
        // Not necessarily broken — it may just be BIG. ark pulls 22.9 GB from
        // SteamCMD and takes ~30 minutes before it binds a port; the 300s check
        // above cannot tell that apart from Terraria sitting dead on an
        // interactive prompt. Ask the guest which one this is.
        const still = await waitOutGameInstall(
          probeServer,
          checkHost,
          checkPort,
          game.protocol,
          step,
          controlSpec(gameFamilyForServer(server as unknown as ServerFamilyLike) ?? "")?.serviceHints[0] ?? null,
          verifyBound
        );
        if (!still.ok) {
          throw new Error(
            `game port ${game.port}/${game.protocol} never opened on ${checkHost}:${checkPort} after ` +
              `~${Math.round(gameCheck.elapsedMs / 1000)}s (${gameCheck.attempts} attempt(s); last error: ` +
              `${gameCheck.error}). SSH is up, but the game server itself never started listening, so this ` +
              `server cannot be handed to the customer as ready. ${still.reason}`
          );
        }
        console.log(`[worker] ${server.hostname}: game port opened after the extended install wait (${still.reason})`);
      }
      // Auto-forward THE PORT A PLAYER ACTUALLY JOINS ON for NAT (non-dedicated-IP)
      // servers. "Plug and play": every game server is reachable the moment it's
      // handed to the customer instead of requiring a manual PortForward from the
      // dashboard first. Found live: a real paying Minecraft customer with no
      // dedicated IP and zero forwards had no path from any public IP to their
      // game port at all. Dedicated IP servers need no forward — their guest port
      // already IS the public port.
      //
      // This is `joinPortFor`, NOT `game.port`. `GAME_PORT` is a health-CHECK map:
      // where an image exposes a TCP port it prefers that one, because a TCP
      // connect is real evidence the game process bound it. For eight families
      // (rust, ark, projectzomboid, factorio, arkasa, soulmask, squad, kf2) that
      // port is RCON/query/admin and the join port is a different, UDP one —
      // `GAME_PORT`'s own comments have always said so. Forwarding off that map
      // therefore published RCON and left the join port unreachable, on every NAT
      // game server of those families. Found live 2026-09-06 on a fresh Rust
      // provision: guest listening on both 28015/udp and 28016/tcp, exactly one
      // game NAT rule (28016/tcp), and the dashboard handing the customer that
      // RCON port as their connect address — no player could ever have joined.
      const joinFam = gameFamilyForServer(server as unknown as ServerFamilyLike);
      const join = joinFam ? joinPortFor(joinFam) : null;
      const checkPortIsAdminOnly = !!join && (join.port !== game.port || join.protocol !== game.protocol);
      // Forward EVERY port the family needs (joinPortsFor), not just the
      // primary one `join` names — found live 2026-09-08: Valheim needs 3
      // consecutive UDP ports to be genuinely joinable, but this loop used to
      // create exactly one PortForward row, leaving every NAT Valheim order
      // needing the customer to manually discover and add the other two
      // (see joinPortsFor's own doc comment for the full incident). `join`
      // itself is kept above unchanged for the admin-port-retraction check
      // below, which only ever concerns the single primary port.
      if (!SANDBOX && !dedicated && joinFam) {
        for (const port of joinPortsFor(joinFam)) {
          try {
            const already = await db.portForward.findFirst({
              where: { serverId: server.id, guestPort: port.port, protocol: port.protocol },
              select: { id: true },
            });
            if (!already) await allocateGameForward(server.nodeId, server.id, port.port, port.protocol);
          } catch (e) {
            // Never fail the whole provision over this — the server is still usable
            // via the dashboard's existing manual "Add forward" as a fallback.
            console.error(`[worker] auto-forward ${port.protocol}/${port.port} failed for ${server.hostname}`, e);
          }
        }
