export function isBlockContiguous(rows: readonly ForwardRow[], specs: readonly ForwardSpec[]): boolean {
  const offsets = blockOffsets(specs);
  const found = specs.map((sp) => rows.find((r) => r.guestPort === sp.guestPort && r.protocol === sp.protocol));
  if (found.some((r) => !r)) return false;
  const base = found[0]!.publicPort - offsets[0];
