/**
 * Move (and complete) one server's block to the lowest free contiguous run,
 * inside a transaction that already holds the IPAM lock. `publicPort` is
 * GLOBALLY unique, so the server's own rows are first parked on temporary
 * negative ports, then written to their final values; the new block may
 * therefore overlap the old one. Rows for ports that did not exist yet are
 * created. Returns the old and new public port per spec.
 */
export async function relocateForwardBlockInTx(
  tx: Tx,
  range: IpamRange,
  serverId: string,
  specs: readonly ForwardSpec[]
): Promise<{ guestPort: number; protocol: string; oldPublic: number | null; newPublic: number }[]> {
  const offsets = blockOffsets(specs);
  const own = await tx.portForward.findMany({
    where: { serverId },
    select: { id: true, publicPort: true, guestPort: true, protocol: true },
  });
  const ownBlock = specs.map((sp) => own.find((r) => r.guestPort === sp.guestPort && r.protocol === sp.protocol) ?? null);
  const skip = new Set(ownBlock.filter((r): r is ForwardRow => !!r).map((r) => r.publicPort));
  // Park the existing block rows so nothing (including ourselves) can collide.
  let t = -1;
  for (const r of ownBlock) if (r) await tx.portForward.update({ where: { id: r.id }, data: { publicPort: t-- } });
  let base: number;
  try {
    const probe = await tx.portForward.findMany({ where: { publicPort: { gte: range.sshPortStart, lte: range.sshPortEnd } }, select: { publicPort: true } });
    const servers = await tx.server.findMany({ where: { sshPort: { gte: range.sshPortStart, lte: range.sshPortEnd } }, select: { sshPort: true } });
    const used = new Set<number>([...probe.map((f) => f.publicPort), ...servers.map((x) => x.sshPort!).filter((x) => x != null)]);
    const b = findContiguousBase(used, range.sshPortStart, range.sshPortEnd, offsets, (p) => isReserved(`port:${p}`) && !skip.has(p));
    if (b === null) throw new Error(`No free consecutive block of ${Math.max(...offsets) + 1} ports in ${range.sshPortStart}-${range.sshPortEnd}`);
    base = b;
  } catch (e) {
    throw e; // the transaction rolls the parking back
  }
  const out: { guestPort: number; protocol: string; oldPublic: number | null; newPublic: number }[] = [];
  for (let i = 0; i < specs.length; i++) {
    const row = ownBlock[i];
    const newPublic = base + offsets[i];
    if (row) await tx.portForward.update({ where: { id: row.id }, data: { publicPort: newPublic } });
    else await tx.portForward.create({ data: { serverId, publicPort: newPublic, guestPort: specs[i].guestPort, protocol: specs[i].protocol } });
    out.push({ guestPort: specs[i].guestPort, protocol: specs[i].protocol, oldPublic: row?.publicPort ?? null, newPublic });
  }
