export async function relocateForwardBlock(
  client: PrismaClient,
  range: IpamRange,
  serverId: string,
  specs: readonly ForwardSpec[]
) {
  await probeAdvisoryLocks();
  const res = await client.$transaction(async (tx) => {
    await lockIpam(tx);
    return relocateForwardBlockInTx(tx, range, serverId, specs);
  });
  for (const r of res) reserve(`port:${r.newPublic}`);
  return res;
}

