/**
 * Repair NAT game servers whose forwarded public ports are not a consecutive
 * block (Valheim 2456/2457/2458 -> 20089/20004/20005 is unjoinable: the client
 * derives the query port as join port + 1). See CONTIGUOUS_FORWARD_FAMILIES in
 * lib/games.ts and allocateGameForwardBlock in lib/ipam.ts.
 *
 * For every RUNNING/STOPPED NAT server (no dedicated IP) of a contiguous family
 * (valheim, ark, projectzomboid) whose join-port forwards are not base+offset,
 * it moves the rows to the lowest free consecutive block (completing any
 * missing row) and queues a SYNC_FORWARDS job, then prints the new address.
 *
 * DRY RUN BY DEFAULT. Pass --apply to write. Optional: --server <hostname|id>.
 *
 *   NXEON_DB_TARGET=nxeon npx tsx scripts/repair-nonconsecutive-forwards.ts
 *   NXEON_DB_TARGET=nxeon npx tsx scripts/repair-nonconsecutive-forwards.ts --apply
 *
 * Affects live customers: the old public port stops working once the sync job
 * runs, so tell the customer their new address (printed below).
 */
import { assertDbTarget } from "./db-target-guard";
assertDbTarget("repair-nonconsecutive-forwards.ts");

import { db } from "../lib/db";
import { ipamRange, isBlockContiguous, relocateForwardBlock } from "../lib/ipam";
import { CONTIGUOUS_FORWARD_FAMILIES, contiguousForwardPorts, joinPortFor, type GameFamily } from "../lib/games";

const APPLY = process.argv.includes("--apply");
const only = process.argv.includes("--server") ? process.argv[process.argv.indexOf("--server") + 1] : null;

async function main() {
  const servers = await db.server.findMany({
    where: {
      status: { in: ["RUNNING", "STOPPED"] },
      dedicatedIp: null,
      ...(only ? { OR: [{ id: only }, { hostname: only }] } : {}),
    },
    select: {
      id: true, hostname: true, nodeId: true,
      gamePlan: { select: { gameFamily: true } },
      osTemplate: { select: { family: true } },
      node: { select: { publicIp: true } },
      portForwards: { select: { id: true, publicPort: true, guestPort: true, protocol: true } },
    },
  });
  let bad = 0, fixed = 0;
  for (const s of servers) {
    const fam = (s.gamePlan?.gameFamily ?? s.osTemplate?.family ?? null) as GameFamily | null;
    if (!fam || !CONTIGUOUS_FORWARD_FAMILIES.has(fam)) continue;
    const block = contiguousForwardPorts(fam);
    if (!block) continue;
    const specs = block.map((p) => ({ guestPort: p.port, protocol: p.protocol }));
    // A server with NO forwards at all is a different problem (never forwarded); skip.
    if (!specs.some((sp) => s.portForwards.some((r) => r.guestPort === sp.guestPort && r.protocol === sp.protocol))) continue;
    if (isBlockContiguous(s.portForwards, specs)) continue;
    bad++;
    const joinGuest = joinPortFor(fam).port;
    const cur = s.portForwards.find((r) => r.guestPort === joinGuest);
    const ip = s.node?.publicIp ?? "<node ip>";
    console.log(`${APPLY ? "FIX " : "WOULD FIX "}${s.hostname} (${fam}) current: ${s.portForwards.map((r) => `${r.guestPort}->${r.publicPort}`).join(", ")}`);
    if (!APPLY) continue;
    try {
      const res = await relocateForwardBlock(db, await ipamRange(s.nodeId), s.id, specs);
      await db.job.create({ data: { type: "SYNC_FORWARDS", serverId: s.id } });
      const join = res.find((r) => r.guestPort === joinGuest)!;
      console.log(`  moved: ${res.map((r) => `${r.guestPort}: ${r.oldPublic ?? "new"} -> ${r.newPublic}`).join(", ")}`);
      console.log(`  NEW ADDRESS ${ip}:${join.newPublic} (was ${cur ? `${ip}:${cur.publicPort}` : "unset"}) - SYNC_FORWARDS queued`);
      fixed++;
    } catch (e: any) {
      console.error(`  FAILED ${s.hostname}: ${String(e?.message ?? e).slice(0, 200)}`);
    }
  }
  console.log(`\n${bad} non-contiguous server(s) found${APPLY ? `, ${fixed} repaired` : " (dry run; re-run with --apply)"}.`);
  await db.$disconnect();
}
main().catch((e) => { console.error(e); process.exit(1); });
