    const base = dir.replace(/^.*\//, "");
    const script =
      `mkdir -p ${shq(GAME_BACKUP_DIR)} && ` +
      `tar czf ${shq(archive)} -C ${shq(parent)} ${shq(base)} 2>&1 && ` +
