  if (field.type !== "string") return null;
  if (v.trim().length === 0) return null;
  if (field.minLength != null && v.length < field.minLength) {
    return `${field.label} must be at least ${field.minLength} characters.`;
  }
  if (field.maxLength != null && v.length > field.maxLength) {
    return `${field.label} is too long (max ${field.maxLength} characters).`;
  }
  if (field.pattern) {
    let re: RegExp | null = null;
    try {
      re = new RegExp(field.pattern, "u");
    } catch {
      re = null;
    }
    if (re && !re.test(v)) return field.patternError ?? `${field.label} contains characters that are not allowed.`;
  }
  return null;
}

