import { test } from "node:test";
import assert from "node:assert/strict";
import {
  allocateBlockWith,
  blockOffsets,
  findContiguousBase,
  isBlockContiguous,
  relocateForwardBlock,
  type IpamRange,
} from "../lib/ipam.ts";
import { CONTIGUOUS_FORWARD_FAMILIES, contiguousForwardPorts, joinPortsFor } from "../lib/games.ts";

/**
 * Consecutive game-port blocks (2026-10-01, customer Jay's Valheim server:
 * 2456/2457/2458 were handed 20089/20004/20005 and nobody could join).
 *
 * The allocator runs against an in-memory fake of the three Prisma calls it
 * makes, INCLUDING the globally-unique PortForward.publicPort constraint (a
 * duplicate throws P2002 like Postgres would), so collisions, exhausted ranges
 * and the move-with-temp-ports trap are exercised for real, with no database.
 */

type Fwd = { id: string; serverId: string; publicPort: number; guestPort: number; protocol: string };

function fakeDb(opts: { sshPorts?: number[]; forwards?: Omit<Fwd, "id">[] } = {}) {
  const forwards: Fwd[] = (opts.forwards ?? []).map((f, i) => ({ id: `seed${i}`, ...f }));
  const sshPorts = [...(opts.sshPorts ?? [])];
  let n = 0;
  const unique = (port: number, ignoreId?: string) => {
    if (forwards.some((f) => f.publicPort === port && f.id !== ignoreId)) {
      throw Object.assign(new Error("Unique constraint failed"), { code: "P2002" });
    }
  };
  const inRange = (v: number, w: any) => (w?.gte == null || v >= w.gte) && (w?.lte == null || v <= w.lte);
  const tx: any = {
    $queryRawUnsafe: async () => [],
    server: {
      findMany: async ({ where }: any) => sshPorts.filter((p) => inRange(p, where.sshPort)).map((sshPort) => ({ sshPort })),
    },
    portForward: {
      findMany: async ({ where }: any) =>
        forwards
          .filter((f) => (where?.serverId == null || f.serverId === where.serverId) && inRange(f.publicPort, where?.publicPort))
          .map((f) => ({ ...f })),
      create: async ({ data }: any) => {
        unique(data.publicPort);
        const row = { id: `new${n++}`, ...data };
        forwards.push(row);
        return row;
      },
      update: async ({ where, data }: any) => {
        const row = forwards.find((f) => f.id === where.id)!;
        unique(data.publicPort, row.id);
        row.publicPort = data.publicPort;
        return row;
      },
    },
  };
  // Rolls back by snapshot on throw, like a real transaction.
  const client: any = {
    $transaction: async (fn: any) => {
      const snap = forwards.map((f) => ({ ...f }));
      try {
        return await fn(tx);
      } catch (e) {
        forwards.splice(0, forwards.length, ...snap);
        throw e;
      }
    },
  };
  return { client, forwards };
}

const range = (start: number, end: number): IpamRange => ({
  nodeId: null, subnetPrefix: "10.20.0.", ipStart: 100, ipEnd: 250,
  sshPortStart: start, sshPortEnd: end, bridge: null, natChain: null,
});
const VAL = [
  { guestPort: 2456, protocol: "udp" as const },
  { guestPort: 2457, protocol: "udp" as const },
  { guestPort: 2458, protocol: "udp" as const },
];

test("findContiguousBase returns the lowest run and skips fragmented gaps", () => {
  assert.equal(findContiguousBase(new Set(), 100, 200, [0, 1, 2]), 100);
  // 100,101 taken; 103 taken -> run of 3 first fits at 104.
  assert.equal(findContiguousBase(new Set([100, 101, 103]), 100, 200, [0, 1, 2]), 104);
  assert.equal(findContiguousBase(new Set([101]), 100, 200, [0, 1]), 102);
  assert.equal(findContiguousBase(new Set(), 100, 101, [0, 1, 2]), null);
  assert.equal(findContiguousBase(new Set([100]), 100, 102, [0, 1, 2]), null);
  assert.equal(findContiguousBase(new Set(), 100, 102, [0, 1, 2]), 100);
  // in-process reservations count as taken
  assert.equal(findContiguousBase(new Set(), 100, 110, [0, 1], (p) => p === 100), 101);
});

test("blockOffsets keeps guest spacing and rejects duplicate guest ports", () => {
  assert.deepEqual(blockOffsets(VAL), [0, 1, 2]);
  assert.deepEqual(blockOffsets([{ guestPort: 7778, protocol: "udp" }, { guestPort: 7777, protocol: "udp" }]), [1, 0]);
  assert.throws(() => blockOffsets([{ guestPort: 27015, protocol: "udp" }, { guestPort: 27015, protocol: "tcp" }]), /twice/);
});

test("a fresh Valheim block is three consecutive public ports mapped 1:1 by offset", async () => {
  const { client, forwards } = fakeDb();
  const ports = await allocateBlockWith(client, range(20000, 20100), "s1", VAL);
  assert.deepEqual(ports, [20000, 20001, 20002]);
  assert.deepEqual(forwards.map((f) => [f.guestPort, f.publicPort]), [[2456, 20000], [2457, 20001], [2458, 20002]]);
});

test("blocks avoid every sshPort and every existing forward (global uniqueness)", async () => {
  const { client } = fakeDb({
    sshPorts: [20000, 20003],
    forwards: [{ serverId: "other", publicPort: 20001, guestPort: 25565, protocol: "tcp" }],
  });
  // free: 20002 | 20004...  -> first run of 3 starts at 20004
  assert.deepEqual(await allocateBlockWith(client, range(20000, 20100), "s1", VAL), [20004, 20005, 20006]);
});

test("two servers never share ports; a second block lands right after the first", async () => {
  const { client } = fakeDb();
  const a = await allocateBlockWith(client, range(30000, 30050), "a", VAL);
  const b = await allocateBlockWith(client, range(30000, 30050), "b", VAL);
  assert.equal(new Set([...a, ...b]).size, 6);
  assert.equal(b[0], a[2] + 1);
});

test("an exhausted or too-fragmented range fails clearly and leaves no partial rows", async () => {
  const { client, forwards } = fakeDb({
    forwards: [
      { serverId: "x", publicPort: 40001, guestPort: 1, protocol: "tcp" },
      { serverId: "x", publicPort: 40003, guestPort: 2, protocol: "tcp" },
    ],
  });
  // 40000, 40002, 40004 free but never three in a row within 40000-40004.
  await assert.rejects(allocateBlockWith(client, range(40000, 40004), "s", VAL), /No free consecutive block of 3/);
  assert.equal(forwards.length, 2);
  // Whole range full.
  await assert.rejects(allocateBlockWith(client, range(40001, 40001), "s", VAL), /No free consecutive block/);
});

test("isBlockContiguous: the exact Jay layout is flagged, a clean block and a partial block behave", () => {
