/**
 * Consecutive game-port blocks (2026-10-01, customer Jay's Valheim server:
 * 2456/2457/2458 were handed 20089/20004/20005 and nobody could join).
 *
 * The allocator runs against an in-memory fake of the three Prisma calls it
 * makes, INCLUDING the globally-unique PortForward.publicPort constraint (a
 * duplicate throws P2002 like Postgres would), so collisions, exhausted ranges
 * and the move-with-temp-ports trap are exercised for real, with no database.
 */

type Fwd = { id: string; serverId: string; publicPort: number; guestPort: number; protocol: string };

function fakeDb(opts: { sshPorts?: number[]; forwards?: Omit<Fwd, "id">[] } = {}) {
  const forwards: Fwd[] = (opts.forwards ?? []).map((f, i) => ({ id: `seed${i}`, ...f }));
  const sshPorts = [...(opts.sshPorts ?? [])];
  let n = 0;
  const unique = (port: number, ignoreId?: string) => {
    if (forwards.some((f) => f.publicPort === port && f.id !== ignoreId)) {
      throw Object.assign(new Error("Unique constraint failed"), { code: "P2002" });
    }
  };
  const inRange = (v: number, w: any) => (w?.gte == null || v >= w.gte) && (w?.lte == null || v <= w.lte);
  const tx: any = {
    $queryRawUnsafe: async () => [],
    server: {
      findMany: async ({ where }: any) => sshPorts.filter((p) => inRange(p, where.sshPort)).map((sshPort) => ({ sshPort })),
    },
    portForward: {
      findMany: async ({ where }: any) =>
        forwards
          .filter((f) => (where?.serverId == null || f.serverId === where.serverId) && inRange(f.publicPort, where?.publicPort))
          .map((f) => ({ ...f })),
      create: async ({ data }: any) => {
        unique(data.publicPort);
        const row = { id: `new${n++}`, ...data };
        forwards.push(row);
        return row;
      },
      update: async ({ where, data }: any) => {
        const row = forwards.find((f) => f.id === where.id)!;
        unique(data.publicPort, row.id);
        row.publicPort = data.publicPort;
        return row;
      },
    },
  };
  // Rolls back by snapshot on throw, like a real transaction.
  const client: any = {
    $transaction: async (fn: any) => {
      const snap = forwards.map((f) => ({ ...f }));
      try {
        return await fn(tx);
      } catch (e) {
        forwards.splice(0, forwards.length, ...snap);
        throw e;
      }
    },
  };
  return { client, forwards };
}

