test("planValheimServerName: untouched default never renames; changes apply; unsafe/password names ignored", () => {
  // existing server renamed by staff: a save with the default must not revert it
  assert.deepEqual(planValheimServerName("Nxeon", "Staff Named", "secret123"), { set: null });
  assert.deepEqual(planValheimServerName(undefined, "Nxeon", "secret123"), { set: null });
  assert.deepEqual(planValheimServerName("", "Nxeon", "secret123"), { set: null });
  assert.deepEqual(planValheimServerName("Jay's Hall", "Nxeon", "secret123"), { set: "Jay's Hall" });
  assert.deepEqual(planValheimServerName("Jay's Hall", "Jay's Hall", "secret123"), { set: null }, "no recreate when already running it");
  assert.match(planValheimServerName("My secret123 server", "Nxeon", "secret123").note ?? "", /password/);
  assert.equal(planValheimServerName("My secret123 server", "Nxeon", "secret123").set, null);
  assert.match(planValheimServerName("bad$name", "Nxeon", "secret123").note ?? "", /Ignored/);
});
